CREATE TABLE metodos_pago(id BIGSERIAL PRIMARY KEY,codigo VARCHAR(30) NOT NULL UNIQUE,nombre VARCHAR(80) NOT NULL,requiere_referencia BOOLEAN NOT NULL DEFAULT FALSE,activo BOOLEAN NOT NULL DEFAULT TRUE);
INSERT INTO metodos_pago(codigo,nombre,requiere_referencia)VALUES('EFECTIVO','Efectivo',FALSE),('YAPE','Yape',TRUE),('PLIN','Plin',TRUE),('TRANSFERENCIA','Transferencia bancaria',TRUE),('TARJETA','Tarjeta',TRUE);
CREATE TABLE cuentas_por_cobrar(id BIGSERIAL PRIMARY KEY,plan_id BIGINT NOT NULL UNIQUE REFERENCES planes_tratamiento(id) ON DELETE RESTRICT,paciente_id BIGINT NOT NULL REFERENCES pacientes(id) ON DELETE RESTRICT,monto_total NUMERIC(12,2) NOT NULL,monto_pagado NUMERIC(12,2) NOT NULL DEFAULT 0,saldo NUMERIC(12,2) NOT NULL,estado VARCHAR(20) NOT NULL DEFAULT 'PENDIENTE',fecha_vencimiento DATE,creado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,actualizado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,version BIGINT NOT NULL DEFAULT 0,CONSTRAINT chk_cuenta_montos CHECK(monto_total>=0 AND monto_pagado>=0 AND saldo>=0 AND saldo=monto_total-monto_pagado),CONSTRAINT chk_cuenta_estado CHECK(estado IN('PENDIENTE','PARCIAL','PAGADA','ANULADA')));
CREATE INDEX idx_cuenta_paciente ON cuentas_por_cobrar(paciente_id,estado);
CREATE TABLE sesiones_caja(id BIGSERIAL PRIMARY KEY,abierta_por BIGINT NOT NULL REFERENCES usuarios(id) ON DELETE RESTRICT,abierta_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,monto_apertura NUMERIC(12,2) NOT NULL,estado VARCHAR(15) NOT NULL DEFAULT 'ABIERTA',cerrada_por BIGINT REFERENCES usuarios(id) ON DELETE RESTRICT,cerrada_en TIMESTAMPTZ,monto_esperado NUMERIC(12,2),monto_contado NUMERIC(12,2),diferencia NUMERIC(12,2),observacion_cierre VARCHAR(1000),version BIGINT NOT NULL DEFAULT 0,CONSTRAINT chk_sesion_estado CHECK(estado IN('ABIERTA','CERRADA')),CONSTRAINT chk_sesion_apertura CHECK(monto_apertura>=0));
CREATE UNIQUE INDEX uq_caja_abierta ON sesiones_caja((estado)) WHERE estado='ABIERTA';
CREATE TABLE pagos(id BIGSERIAL PRIMARY KEY,cuenta_id BIGINT NOT NULL REFERENCES cuentas_por_cobrar(id) ON DELETE RESTRICT,paciente_id BIGINT NOT NULL REFERENCES pacientes(id) ON DELETE RESTRICT,plan_id BIGINT NOT NULL REFERENCES planes_tratamiento(id) ON DELETE RESTRICT,sesion_caja_id BIGINT NOT NULL REFERENCES sesiones_caja(id) ON DELETE RESTRICT,metodo_pago_id BIGINT NOT NULL REFERENCES metodos_pago(id) ON DELETE RESTRICT,monto NUMERIC(12,2) NOT NULL,referencia VARCHAR(120),numero_constancia VARCHAR(30) NOT NULL UNIQUE,estado VARCHAR(20) NOT NULL DEFAULT 'REGISTRADO',registrado_por BIGINT NOT NULL REFERENCES usuarios(id) ON DELETE RESTRICT,confirmado_por BIGINT NOT NULL REFERENCES usuarios(id) ON DELETE RESTRICT,registrado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,anulado_por BIGINT REFERENCES usuarios(id),anulado_en TIMESTAMPTZ,motivo_anulacion VARCHAR(500),version BIGINT NOT NULL DEFAULT 0,CONSTRAINT chk_pago_monto CHECK(monto>0),CONSTRAINT chk_pago_estado CHECK(estado IN('REGISTRADO','ANULADO')));
CREATE INDEX idx_pago_fecha ON pagos(registrado_en DESC);CREATE INDEX idx_pago_cuenta ON pagos(cuenta_id,estado);
CREATE TABLE gastos(id BIGSERIAL PRIMARY KEY,sesion_caja_id BIGINT NOT NULL REFERENCES sesiones_caja(id) ON DELETE RESTRICT,categoria VARCHAR(80) NOT NULL,descripcion VARCHAR(500) NOT NULL,proveedor VARCHAR(150),documento_referencia VARCHAR(80),metodo_pago_id BIGINT NOT NULL REFERENCES metodos_pago(id),monto NUMERIC(12,2) NOT NULL,estado VARCHAR(20) NOT NULL DEFAULT 'REGISTRADO',registrado_por BIGINT NOT NULL REFERENCES usuarios(id),confirmado_por BIGINT NOT NULL REFERENCES usuarios(id),registrado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,anulado_por BIGINT REFERENCES usuarios(id),anulado_en TIMESTAMPTZ,motivo_anulacion VARCHAR(500),version BIGINT NOT NULL DEFAULT 0,CONSTRAINT chk_gasto_monto CHECK(monto>0),CONSTRAINT chk_gasto_estado CHECK(estado IN('REGISTRADO','ANULADO')));
CREATE INDEX idx_gasto_fecha ON gastos(registrado_en DESC);
CREATE TABLE movimientos_caja(id BIGSERIAL PRIMARY KEY,sesion_caja_id BIGINT NOT NULL REFERENCES sesiones_caja(id),tipo VARCHAR(15) NOT NULL,categoria VARCHAR(80) NOT NULL,origen VARCHAR(30) NOT NULL,origen_id BIGINT NOT NULL,metodo_pago_id BIGINT REFERENCES metodos_pago(id),monto NUMERIC(12,2) NOT NULL,descripcion VARCHAR(500) NOT NULL,creado_por BIGINT NOT NULL REFERENCES usuarios(id),creado_en TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT chk_movimiento_tipo CHECK(tipo IN('INGRESO','EGRESO')),CONSTRAINT chk_movimiento_monto CHECK(monto>0));
CREATE INDEX idx_movimiento_sesion ON movimientos_caja(sesion_caja_id,creado_en);
